BEGIN;

INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: medium / L2 — Dissolution clause requirement (organizational test)
(3, 'Tax-Exempt Organizations', 'Bright Horizons Academy, a nonprofit seeking 501(c)(3) status, submits articles of incorporation that limit its purposes to educational activities. However, the articles contain no provision regarding distribution of assets upon dissolution. Under the organizational test, what is the effect of this omission?', '["The application will be denied because the organizational test requires a dissolution clause directing assets to another exempt organization or government", "The application will be approved because limiting purposes to education satisfies the organizational test", "The application will be conditionally approved pending a board resolution to add the clause later", "The application will be approved because dissolution provisions are only required for private foundations"]'::jsonb, 0, 'Under IRC Section 501(c)(3), the organizational test requires governing documents to include a dissolution clause directing assets to another exempt organization or government upon dissolution. Merely limiting purposes to exempt activities is insufficient without this clause. Option B is incorrect because the organizational test has multiple requirements, including both purpose limitation and the dissolution provision.', 'medium', 2),

-- Q2: hard / L4 — Controlled entity payments vs passive income UBIT
(3, 'Tax-Exempt Organizations', 'Mercy Health Alliance, a 501(c)(3) hospital system, owns 100% of two subsidiaries. Subsidiary A pays $400,000 in rent at fair market value for use of the hospital''s medical office building. Subsidiary B pays $200,000 in royalties, but an independent appraisal values the license at $120,000. Mercy also receives $150,000 in dividends from publicly traded stock. Evaluate how each income stream is treated under the UBIT rules for controlled entity payments and passive income exclusions.', '["All three amounts are excluded as passive income under Section 512(b)", "Only the dividends are excluded; all rents and royalties from controlled subsidiaries are UBIT", "The rent from Subsidiary A is excluded, the $80,000 excess royalty from Subsidiary B is UBIT, and the dividends are excluded", "The rent and royalties are both UBIT in full; only dividends from unrelated entities qualify for the passive income exclusion"]'::jsonb, 2, 'Under IRC Section 512(b)(13), rent, interest, and royalties from a controlled subsidiary (80%+ ownership) are UBIT only to the extent they exceed fair market value. The $400,000 rent at FMV is excluded, but $80,000 of the $200,000 royalty exceeds the $120,000 FMV and is UBIT. Dividends from publicly traded stock are excluded under the general passive income rule. Option B is incorrect because it treats all controlled-entity payments as UBIT regardless of whether they exceed FMV.', 'hard', 4),

-- Q3: easy / L1 — 501(h) election for lobbying expenditure test
(3, 'Tax-Exempt Organizations', 'What does the Section 501(h) election allow a 501(c)(3) organization to do?', '["Engage in unlimited political campaign activity", "Use specific dollar thresholds to measure permissible lobbying expenditures", "Avoid filing Form 990 for three consecutive years", "Exclude all unrelated business income from taxation"]'::jsonb, 1, 'Under IRC Section 501(h), eligible 501(c)(3) organizations may elect to use specific expenditure-based dollar thresholds rather than the vague ''substantial part'' test to measure permissible lobbying. This provides a safe harbor with clear limits. Option A is incorrect because political campaign activity remains absolutely prohibited regardless of any election.', 'easy', 1),

-- Q4: medium / L2 — One-third support test (Section 509(a)(1))
(3, 'Tax-Exempt Organizations', 'Heritage Music Foundation receives 40% of its total support from government grants and general public contributions, 35% from program service fees, and 25% from investment income. The organization seeks public charity status. Under the one-third support test of Section 509(a)(1), how is Heritage classified?', '["Private foundation, because investment income exceeds one-third of support", "Public charity, because total support from all sources exceeds one-third", "Private foundation, because program service fees are not counted toward public support", "Public charity, because government grants and public contributions exceed one-third of total support"]'::jsonb, 3, 'Under IRC Section 509(a)(1), an organization qualifies as a public charity if it receives a substantial part of support from government or general public sources, generally meeting the one-third threshold. Heritage receives 40% from such sources, satisfying the test. Option A is incorrect because the test focuses on the proportion of public and government support, not on whether other income categories exceed one-third.', 'medium', 2),

-- Q5: easy / L2 — Form 990-N e-Postcard threshold
(3, 'Tax-Exempt Organizations', 'Neighborhood Watch Coalition, a small 501(c)(3), has gross receipts of $35,000 and total assets of $40,000 for 2025. Which annual information return must the organization file with the IRS?', '["Form 990, the full annual information return", "Form 990-EZ, the simplified annual return", "Form 990-N (e-Postcard), the electronic notice", "No annual filing is required for organizations this small"]'::jsonb, 2, 'Under IRC Section 6033, organizations with gross receipts normally $50,000 or less may file Form 990-N (e-Postcard), an electronic notice requiring only basic information such as name, address, and EIN. Option B is incorrect because Form 990-EZ applies to organizations with gross receipts under $200,000 and assets under $500,000 that exceed the 990-N threshold.', 'easy', 2),

-- Q6: medium / L2 — Churches/schools/hospitals automatic public charity
(3, 'Tax-Exempt Organizations', 'St. Andrew''s Hospital is a 501(c)(3) organization that receives 90% of its funding from a single private donor and 10% from patient fees. The hospital''s board is concerned about private foundation classification. Under Section 509, how is St. Andrew''s Hospital classified?', '["Private foundation, because it fails the one-third public support test", "Private foundation, because a single donor provides most of the support", "Public charity only if it elects supporting organization status under Section 509(a)(3)", "Public charity, because hospitals are automatically classified as public charities regardless of funding sources"]'::jsonb, 3, 'Under IRC Section 509(a)(1) and Section 170(b)(1)(A)(iii), hospitals are automatically classified as public charities regardless of their funding sources. The one-third support test is irrelevant for organizations qualifying by category. Option A is incorrect because category-based classifications (churches, schools, hospitals) override the support tests entirely.', 'medium', 2),

-- Q7: medium / L3 — Personal property rents UBIT treatment
(3, 'Tax-Exempt Organizations', 'River Valley Education Foundation, a 501(c)(3), leases a building to a local business. The lease includes office furniture and computer equipment. Annual rent is $60,000 for the building and $25,000 for the personal property. The foundation has no debt on the building. Apply the personal property rent rules to determine the UBIT treatment.', '["All $85,000 is excluded as passive rental income", "The $25,000 personal property rent is subject to UBIT because personal property rent exceeds 10% of total rent under the lease", "The entire $85,000 is subject to UBIT because mixed leases are never excluded", "Only $8,500 (10% of total rent) is subject to UBIT"]'::jsonb, 1, 'Under IRC Section 512(b)(3), rents from real property are generally excluded from UBIT, but rents from personal property are included unless incidental (less than 10% of total rents under the lease). Here personal property rent is $25,000/$85,000 = 29.4%, exceeding the 10% threshold, so the $25,000 portion is UBIT. Option A is incorrect because the personal property exclusion only applies when such rents fall below 10% of total rent under the lease.', 'medium', 3),

-- Q8: easy / L1 — Private inurement prohibition
(3, 'Tax-Exempt Organizations', 'What does the private inurement prohibition under Section 501(c)(3) prevent?', '["Any part of net earnings from benefiting private shareholders or individuals who are insiders", "The organization from earning any profit on its activities", "Donors from receiving a charitable contribution deduction", "The organization from investing in publicly traded securities"]'::jsonb, 0, 'Under IRC Section 501(c)(3), the private inurement prohibition prevents any part of the organization''s net earnings from inuring to the benefit of private shareholders or individuals who are insiders such as founders, officers, and directors. Option B is incorrect because exempt organizations may earn profits — the prohibition targets improper distribution of earnings to insiders, not profit-making itself.', 'easy', 1),

-- Q9: medium / L2 — Research exclusion from UBIT
(3, 'Tax-Exempt Organizations', 'Lakewood University, a 501(c)(3) institution, performs three categories of research: government-contracted defense research ($300,000), pharmaceutical company-sponsored proprietary research ($200,000), and faculty research published in peer-reviewed journals ($150,000). Which research income is excluded from UBIT?', '["Only the $300,000 government-contracted research", "Only the $150,000 publicly available research", "The $300,000 government research and the $150,000 publicly available research", "All $650,000, because university research is automatically excluded"]'::jsonb, 2, 'Under IRC Section 512(b)(7)-(9), research performed for the government or by a college/university is excluded from UBIT, as is research whose results are freely available to the public. The proprietary pharmaceutical research does not qualify because its results are not publicly available and it is not government-contracted. Option D is incorrect because only research meeting specific statutory criteria is excluded.', 'medium', 2),

-- Q10: medium / L3 — Filing deadline computation
(3, 'Tax-Exempt Organizations', 'Coastal Conservation Trust, a 501(c)(3) with a fiscal year ending September 30, needs to file its Form 990. The organization''s accountant is unsure of the deadline. Apply the Form 990 filing deadline rules to determine when the return is due.', '["January 15 of the following year (15th day of the 4th month)", "March 15 of the following year (15th day of the 6th month)", "December 15 of the same year (15th day of the 3rd month)", "February 15 of the following year (15th day of the 5th month)"]'::jsonb, 3, 'Under IRC Section 6033, Form 990 is due on the 15th day of the 5th month after the end of the organization''s tax year. For a September 30 fiscal year-end, the 5th month is February, making the deadline February 15 of the following year. Option A is incorrect because January is only the 4th month after a September year-end, not the 5th.', 'medium', 3),

-- Q11: hard / L3 — Section 4945 expenditure responsibility for grants
(3, 'Tax-Exempt Organizations', 'Pearlman Family Foundation, a private foundation, makes three grants: (1) $100,000 to a 501(c)(3) public charity for disaster relief, (2) $75,000 to a 501(c)(4) social welfare organization for community education, and (3) $50,000 directly to a graduate student for dissertation research without prior IRS approval of the selection process. Analyze which grants are taxable expenditures under Section 4945.', '["Only the $50,000 student grant, because individual grants always violate Section 4945", "The $75,000 to the 501(c)(4) and the $50,000 student grant", "Only the $75,000 to the 501(c)(4), because grants to non-charities require expenditure responsibility", "The $75,000 grant without expenditure responsibility and the $50,000 student grant without IRS-approved selection criteria are both taxable expenditures"]'::jsonb, 3, 'Under IRC Section 4945, grants to non-501(c)(3) organizations are taxable expenditures unless the foundation exercises expenditure responsibility. The 501(c)(4) grant lacks this safeguard. Grants to individuals for study or research are taxable expenditures unless the selection process has prior IRS approval. The public charity grant is not a taxable expenditure. Option A is incorrect because individual grants are permitted when the selection criteria have prior IRS approval.', 'hard', 3),

-- Q12: medium / L3 — NOL deduction for UBIT
(3, 'Tax-Exempt Organizations', 'Greenleaf Community Center, a 501(c)(3), had $40,000 of net unrelated business loss in 2024 and $55,000 of net unrelated business income in 2025. The center also had $20,000 of investment income (dividends) in 2025. Apply the UBIT net operating loss rules to determine the 2025 unrelated business taxable income.', '["$15,000 ($55,000 minus $40,000 NOL)", "$14,000 ($55,000 minus $40,000 NOL, minus $1,000 specific deduction)", "Negative $5,000 ($55,000 minus $40,000 NOL, minus $20,000 dividends)", "$55,000, because prior-year losses cannot offset current UBIT"]'::jsonb, 1, 'Under IRC Section 512(b)(6), UBIT allows a net operating loss deduction computed using only unrelated business income items. The $40,000 loss carries forward to offset 2025 UBI ($55,000 - $40,000 = $15,000), then the $1,000 specific deduction applies, yielding $14,000. Option C is incorrect because dividends are excluded from UBIT and cannot reduce unrelated business taxable income.', 'medium', 3),

-- Q13: easy / L1 — Form 990-PF requirement for all private foundations
(3, 'Tax-Exempt Organizations', 'Which organizations must file Form 990-PF regardless of their size?', '["All 501(c)(3) public charities", "Only private foundations with gross receipts over $200,000", "All private foundations regardless of size", "Only private foundations that have net investment income"]'::jsonb, 2, 'Under IRC Section 6033, all private foundations must file Form 990-PF annually regardless of their size or gross receipts. This form includes detailed financial reporting and excise tax computations. Option B is incorrect because the $200,000 threshold applies to the distinction between Form 990 and Form 990-EZ for public charities, not to private foundation filing requirements.', 'easy', 1),

-- Q14: hard / L4 — Additional tax on excess benefit (200% if not corrected)
(3, 'Tax-Exempt Organizations', 'Dr. Rivera, the executive director of Beacon Health Foundation (a 501(c)(3)), receives $1,200,000 in total compensation when comparable positions pay $450,000. The board had no independent compensation study and did not document its reasoning. The IRS determines the excess benefit is $750,000. Dr. Rivera does not return the excess amount within the taxable period. Evaluate the total excise tax exposure for Dr. Rivera and any participating board members under Section 4958.', '["$1,687,500 on Dr. Rivera ($187,500 initial at 25% plus $1,500,000 additional at 200%) plus up to $20,000 per participating board member (10% of excess, capped)", "$187,500 on Dr. Rivera (25% initial tax only) plus 10% on participating board members with no cap", "$750,000 on Dr. Rivera (100% of excess benefit) with no liability for board members", "$150,000 on Dr. Rivera (20% of excess benefit) plus 5% on participating board members"]'::jsonb, 0, 'Under IRC Section 4958, the initial tax on a disqualified person is 25% of the excess benefit ($750,000 x 25% = $187,500). If not corrected within the taxable period, an additional 200% tax applies ($750,000 x 200% = $1,500,000). Organization managers who knowingly participate owe 10% of the excess benefit, capped at $20,000 per transaction. Option B is incorrect because it omits the additional 200% tax triggered by failure to correct the excess benefit.', 'hard', 4),

-- Q15: medium / L3 — Bingo game exclusion application
(3, 'Tax-Exempt Organizations', 'Mountain View Senior Center, a 501(c)(3), operates weekly bingo nights generating $45,000 annually. The bingo games are legal under state law, and no commercial bingo operations exist in the jurisdiction. All prizes are cash. Apply the UBIT exclusion rules to determine the tax treatment of the bingo income.', '["Subject to UBIT because cash prizes make it a commercial activity", "Subject to UBIT because bingo is a regularly carried on trade or business", "Excluded only if substantially all labor is performed by volunteers", "Excluded from UBIT under the statutory bingo exclusion because the games are legal and commercial bingo is not ordinarily carried on in the jurisdiction"]'::jsonb, 3, 'Under IRC Section 513(f), bingo games are excluded from UBIT when conducted legally and when commercial bingo is not ordinarily carried on in the same jurisdiction. Both conditions are met here. Option A is incorrect because the statutory bingo exclusion does not depend on the form of prizes — it depends on the legal status of the games and the absence of competing commercial bingo.', 'medium', 3),

-- Q16: medium / L3 — Convenience exclusion application
(3, 'Tax-Exempt Organizations', 'State University Medical School, a 501(c)(3), operates an on-campus cafeteria that serves breakfast and lunch exclusively to medical students, faculty, and hospital staff. No outside customers are admitted. The cafeteria generates $180,000 in annual revenue. Apply the UBIT convenience exclusion to determine the tax treatment.', '["Subject to UBIT because the cafeteria earns revenue regularly from selling food", "Excluded from UBIT under the convenience exclusion because the activity is conducted for the convenience of students and employees", "Excluded from UBIT only if all cafeteria workers are unpaid volunteers", "Subject to UBIT because food service is not related to medical education"]'::jsonb, 1, 'Under IRC Section 513(a)(2), activities conducted primarily for the convenience of members, students, patients, or employees are excluded from UBIT even if they meet the three-part test. Because the cafeteria serves only students, faculty, and staff, the convenience exclusion applies. Option D is incorrect because the convenience exclusion operates independently of the substantially related analysis, focusing on whom the activity serves.', 'medium', 3),

-- Q17: hard / L4 — Private benefit vs private inurement distinction
(3, 'Tax-Exempt Organizations', 'Sunrise Learning Academy, a 501(c)(3) tutoring center, enters two arrangements: (1) it pays its founder-director a $500,000 salary when comparable positions pay $180,000, and (2) it contracts exclusively with the founder''s friend (a non-insider with no organizational role) to provide all tutoring materials at 40% above market price. Evaluate how the IRS would characterize each arrangement under the private inurement and private benefit doctrines.', '["Both are private inurement subject to Section 4958 intermediate sanctions", "The salary is private benefit; the materials contract is private inurement because it involves procurement", "The salary is private inurement (insider) subject to Section 4958; the materials contract is impermissible private benefit (non-insider) threatening exempt status", "Neither arrangement violates exempt status because the organization has discretion in setting compensation and selecting vendors"]'::jsonb, 2, 'Under IRC Section 501(c)(3), private inurement prohibits earnings from benefiting insiders, while private benefit is broader and covers non-insiders. The founder-director''s excess salary is private inurement subject to Section 4958 intermediate sanctions. The friend''s overpriced contract is private benefit (not inurement since the friend is not an insider), which threatens exempt status under the operational test. Option A is wrong because Section 4958 applies to disqualified persons (insiders), not non-insiders receiving private benefit.', 'hard', 4),

-- Q18: easy / L1 — Supporting organization (Section 509(a)(3))
(3, 'Tax-Exempt Organizations', 'What is a supporting organization under Section 509(a)(3)?', '["An organization that provides financial auditing services to private foundations", "An organization that lobbies on behalf of multiple 501(c)(3) charities", "An organization that receives more than one-third support from a single donor", "An organization operated exclusively to support one or more public charities"]'::jsonb, 3, 'Under IRC Section 509(a)(3), a supporting organization is one organized and operated exclusively for the benefit of, to perform the functions of, or to carry out the purposes of one or more public charities, allowing it to be classified as a public charity. Option C is incorrect because it describes a funding pattern associated with private foundations, not the definition of a supporting organization.', 'easy', 1),

-- Q19: medium / L2 — Penalty for failure to file (daily rate)
(3, 'Tax-Exempt Organizations', 'Children''s Discovery Center, a 501(c)(3) with gross receipts of $400,000, files its Form 990 seventy-five days late without reasonable cause. Under IRC Section 6652(c), what penalty does the organization face?', '["$1,500 ($20 per day for 75 days)", "$7,500 ($100 per day for 75 days)", "$20,000 flat penalty for late filing", "No penalty, because the organization has less than $500,000 in gross receipts"]'::jsonb, 0, 'Under IRC Section 6652(c), the penalty for late filing of Form 990 is $20 per day (up to $10,500 or 5% of gross receipts, whichever is less) for organizations with gross receipts under $1,186,000. At $20/day for 75 days, the penalty is $1,500. Option B is incorrect because the $100/day rate is reserved for larger organizations with gross receipts of $1,186,000 or more.', 'medium', 2),

-- Q20: medium / L2 — Form 990 Schedule A purpose
(3, 'Tax-Exempt Organizations', 'During its annual filing, the board treasurer of Parkview Education Alliance asks the CPA which Form 990 schedule documents the organization''s public charity classification. Which schedule does the CPA identify?', '["Schedule B — Schedule of Contributors", "Schedule J — Compensation Information", "Schedule A — Public Charity Status and Public Support", "Schedule D — Supplemental Financial Statements"]'::jsonb, 2, 'Under IRC Section 6033, Form 990 Schedule A reports the organization''s public charity status and public support calculations, demonstrating whether it meets the requirements to avoid private foundation classification. Option B is incorrect because Schedule J reports compensation information for officers, directors, and key employees, not public charity classification.', 'medium', 2),

-- Q21: medium / L3 — Foundation manager self-dealing tax (5%)
(3, 'Tax-Exempt Organizations', 'The CEO of Atlas Medical Foundation (a private foundation) leases her personal vacation property to the foundation for $3,000 per month, totaling $36,000 annually. The foundation''s general counsel reviews the lease, knows the CEO is a disqualified person, and approves the transaction. Apply Section 4941 to determine the excise tax on the general counsel.', '["No tax, because the general counsel is not a disqualified person", "$3,600 (10% of the lease amount, same as the self-dealer''s rate)", "No tax, because the rent was at or below market value", "$1,800 (5% of $36,000) for knowingly participating in a self-dealing transaction"]'::jsonb, 3, 'Under IRC Section 4941, a foundation manager who knowingly participates in a self-dealing transaction is subject to a 5% initial tax on the amount involved. The general counsel knew the CEO was a disqualified person and approved the lease, triggering the 5% tax ($36,000 x 5% = $1,800). Option C is incorrect because self-dealing is based on the nature of the transaction — even below-market-rate leases between a foundation and disqualified persons are prohibited.', 'medium', 3),

-- Q22: medium / L2 — Gross receipts test (Section 509(a)(2))
(3, 'Tax-Exempt Organizations', 'Riverdale Community Theater, a 501(c)(3), receives $250,000 in ticket sales, $80,000 in membership fees, $50,000 in public donations, and $120,000 from investment income. The theater seeks public charity classification under the gross receipts test. Under Section 509(a)(2), which revenue sources count toward the one-third support requirement?', '["Only the $50,000 in public donations", "Ticket sales ($250,000), membership fees ($80,000), and public donations ($50,000)", "All $500,000 including investment income", "Only ticket sales ($250,000) and membership fees ($80,000)"]'::jsonb, 1, 'Under IRC Section 509(a)(2), support is measured by contributions, membership fees, and gross receipts from activities related to exempt functions. Ticket sales, membership fees, and public donations all qualify. Investment income does not count toward the one-third support calculation. Option D is incorrect because it excludes public donations, which are counted as contributions under Section 509(a)(2).', 'medium', 2),

-- Q23: medium / L2 — Private foundation presumption
(3, 'Tax-Exempt Organizations', 'New Beginnings Youth Mentoring, a newly formed 501(c)(3), receives its determination letter but does not apply for public charity status. The organization''s board assumes it will be treated as a public charity because it serves the community. Under Section 509, what is the organization''s default classification?', '["Public charity, because all 501(c)(3) organizations are presumed to be public charities", "Exempt but unclassified until the first Form 990 is filed", "Public charity for the first five years, then reclassified based on support", "Private foundation, because all 501(c)(3) organizations are presumed to be private foundations unless they demonstrate public charity status"]'::jsonb, 3, 'Under IRC Section 509(a), every 501(c)(3) organization is presumed to be a private foundation unless it affirmatively demonstrates it qualifies as a public charity under one of the statutory exceptions. The board''s assumption is incorrect. Option A is incorrect because it reverses the statutory presumption — the default classification is private foundation, not public charity.', 'medium', 2),

-- Q24: hard / L4 — Excess business holdings combined limit analysis
(3, 'Tax-Exempt Organizations', 'Garrett Family Foundation (a private foundation) owns 12% of voting stock in Apex Industries. The founder''s children (disqualified persons) independently own 15% of Apex voting stock. An unrelated third party owns the remaining 73%. The foundation''s investment advisor recommends purchasing an additional 5% block of Apex stock, bringing the foundation''s holdings to 17%. Evaluate whether the proposed acquisition violates Section 4943.', '["The acquisition violates Section 4943 because the combined holdings of the foundation (17%) plus disqualified persons (15%) total 32%, exceeding the 20% permitted holdings limit, triggering a 10% excise tax on the excess", "The acquisition is permissible because the foundation''s direct holdings of 17% do not exceed 20%", "The acquisition violates Section 4943 only if the foundation''s direct holdings exceed 35%", "The acquisition is permissible because disqualified persons'' holdings are counted separately from the foundation''s holdings"]'::jsonb, 0, 'Under IRC Section 4943, a private foundation and all disqualified persons combined may not hold more than 20% of voting stock of a business enterprise. The combined holdings are already 27% (12% + 15%), exceeding 20%. Adding 5% increases the total to 32%. A 10% initial excise tax applies to the excess holdings. Option B is incorrect because Section 4943 requires combining foundation and disqualified person holdings when testing the 20% limit.', 'hard', 4),

-- Q25: easy / L1 — Section 4940 excise tax rate on net investment income
(3, 'Tax-Exempt Organizations', 'What is the excise tax rate imposed on a private foundation''s net investment income under Section 4940?', '["2% of net investment income", "1.39% of net investment income", "5% of net investment income", "10% of net investment income"]'::jsonb, 1, 'Under IRC Section 4940, private foundations are subject to a 1.39% excise tax on net investment income, including interest, dividends, rents, royalties, and capital gains. Option A is incorrect because the rate was reduced from 2% to 1.39% by the Taxpayer Certainty and Disaster Tax Relief Act of 2019.', 'easy', 1),

-- Q26: medium / L3 — Form 8868 extension application
(3, 'Tax-Exempt Organizations', 'Lighthouse Homeless Services, a 501(c)(3) calendar-year organization, realizes on May 10, 2026, that its Form 990 financial data will not be ready by the May 15 deadline. The executive director asks the accountant how to obtain additional time. Apply the extension rules to identify the correct procedure and resulting deadline.', '["File Form 4868 for an automatic 6-month extension, making the new deadline November 15", "No extension is available for Form 990; the organization must file by May 15 or face penalties", "File Form 8868 for an automatic 6-month extension, making the new deadline November 15", "Request a 3-month extension from the IRS district office, making the new deadline August 15"]'::jsonb, 2, 'Under IRC Section 6081, tax-exempt organizations use Form 8868 to obtain an automatic 6-month extension for filing Form 990. For a calendar-year organization with a May 15 deadline, the extended deadline is November 15. Option A is incorrect because Form 4868 is used by individual taxpayers for personal income tax returns, not by tax-exempt organizations.', 'medium', 3),

-- Q27: hard / L4 — UBIT decision tree multi-factor analysis
(3, 'Tax-Exempt Organizations', 'Pacific Arts Institute, a 501(c)(3) museum, runs three activities: (1) an annual two-day art fair where volunteers sell donated artwork, generating $90,000; (2) a year-round parking garage open to the public, generating $200,000; and (3) a summer art camp for children taught by paid instructors, generating $60,000 in tuition. Evaluate each activity through the UBIT three-part test and statutory exclusions to determine which produce unrelated business taxable income.', '["All three activities are subject to UBIT because they generate income from sales and services", "Only the parking garage income ($200,000) is subject to UBIT", "The art fair ($90,000) and parking garage ($200,000) are subject to UBIT", "None of the activities are subject to UBIT because all revenue supports the museum''s exempt mission"]'::jsonb, 1, 'Under IRC Sections 512-513, the art fair is excluded by two statutory exclusions: volunteer labor and donated goods. The summer art camp is substantially related to the museum''s educational mission, failing the third prong of the three-part test. The parking garage is a trade or business, regularly carried on, and not substantially related to art education with no exclusion applying. Option C is incorrect because the art fair qualifies for multiple exclusions (volunteers and donated merchandise).', 'hard', 4),

-- Q28: easy / L1 — Schedule J compensation reporting
(3, 'Tax-Exempt Organizations', 'What information does Form 990 Schedule J report?', '["Compensation of officers, directors, and key employees", "Detailed listing of all organizational assets and liabilities", "Names and addresses of all donors contributing over $5,000", "Calculations of unrelated business taxable income"]'::jsonb, 0, 'Under IRC Section 6033, Form 990 Schedule J reports compensation information for current and former officers, directors, trustees, key employees, and highest compensated employees, increasing transparency around executive pay. Option C is incorrect because donor information is reported on Schedule B (Schedule of Contributors), which is confidential.', 'easy', 1),

-- Q29: easy / L1 — Operational test primary requirement
(3, 'Tax-Exempt Organizations', 'Under the operational test, what must a 501(c)(3) organization demonstrate?', '["That it has filed articles of incorporation in its state of organization", "That it is operated primarily for one or more exempt purposes", "That it receives at least one-third of support from public sources", "That it files Form 990 by the annual deadline"]'::jsonb, 1, 'Under IRC Section 501(c)(3), the operational test requires that the organization be operated primarily for exempt purposes, meaning it engages primarily in activities that accomplish its stated exempt purpose. Option A is incorrect because filing articles of incorporation relates to the organizational test, not the operational test.', 'easy', 1),

-- Q30: easy / L1 — Section 4945 taxable expenditures definition
(3, 'Tax-Exempt Organizations', 'Under Section 4945, what are taxable expenditures for a private foundation?', '["Amounts spent on lobbying, political activity, unapproved individual grants, and grants to non-charities without expenditure responsibility", "Any expenditure exceeding $100,000 in a single fiscal year", "All administrative expenses including salaries and office rent", "Grants made exclusively to public charities for charitable purposes"]'::jsonb, 0, 'Under IRC Section 4945, taxable expenditures include amounts for lobbying, political campaign intervention, grants to individuals without IRS-approved selection procedures, and grants to non-501(c)(3) organizations without expenditure responsibility. The initial excise tax is 20% on such expenditures. Option D is incorrect because grants to public charities are generally not taxable expenditures.', 'easy', 1)
;

COMMIT;
